struct Cell {
    int precision;
    Integer x, y;
    bool operator<(const Cell &other) const { return std::tie(precision, x, y) < std::tie(other.precision, other.x, other.y); }
    bool operator==(const Cell &other) const { return precision == other.precision && x == other.x && y == other.y; }
